import html.parser, pathlib, re

class T(html.parser.HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out=[]; self.skip=0
    def handle_starttag(self, tag, attrs):
        if tag in ("script","style"): self.skip+=1
        if tag in ("h1","h2","h3","li","p","dt","dd"):
            self.out.append("\n")
            if tag.startswith("h"): self.out.append("#"*int(tag[1])+" ")
    def handle_endtag(self, tag):
        if tag in ("script","style"): self.skip-=1
    def handle_data(self, d):
        if not self.skip and d.strip(): self.out.append(d.strip()+" ")

for f in ["index.html","publications.html","blog.html"]:
    t=T(); t.feed(pathlib.Path(f).read_text())
    text=re.sub(r"[ \t]+"," ", "".join(t.out))
    print("="*70); print(f); print("="*70)
    print("\n".join(l for l in text.splitlines() if l.strip())[:1800])
EOF
